      "path": "packages/dsh-web-all/src/index.ts",
      "content": "/**\n * Host half of the dsh-web family aggregate: the fault-isolation shell.\n * Patch rows generated by scripts/aggregate.mjs mount THIS package and carry\n * the real plugin package name in the row config (`config.plugin`); apply\n * imports and mounts the real module behind an isolation boundary, so one\n * broken plugin degrades alone instead of rolling back the whole boot group.\n * The browser half (./client) carries the compat shim that stamps the legacy\n * DOM hooks (data-pane / data-dsh-frame) the family plugins and skins expect\n * onto current dsh web shells.\n */\nimport type { Context } from '@deepseek-ai/cordis'\nimport { apply as shellApply } from './shell.ts'\nimport type { ShellConfigInput } from './shell.ts'\n\n/** Required services: none — the shell must activate before anything else. */\nexport const inject = [] as const\n\n/** Host plugin body: mount the configured real plugin behind the shell boundary. */\nexport function apply(ctx: Context, config: ShellConfigInput): Promise<void> {\n  return shellApply(ctx, config)\n}\n"
